"""
Market Analysis Agent.

This agent uses LLM to analyze market intelligence and provide strategic insights.
Integrates with Overmind for tracing and optimization.
"""
from typing import Any, Dict, List, Optional
from datetime import datetime
from dataclasses import dataclass

from shared.agents.overmind_integration import BaseAgent, OvermindTracer
from shared.agents.cursor_integration import CursorComposerService


@dataclass
class MarketInsight:
    """Strategic market insight generated by agent."""
    
    insight_type: str
    summary: str
    evidence: List[str]
    confidence: float
    actionability: str
    urgency: str
    recommendations: List[str]


@dataclass
class CompetitiveAnalysis:
    """Competitive analysis result."""
    
    competitor_movements: List[Dict]
    market_opportunities: List[Dict]
    threat_assessment: str
    strategic_position: str


class MarketAnalysisAgent(BaseAgent):
    """
    Market Analysis Agent.
    
    This agent:
    - Analyzes market intelligence from Tavily and other sources
    - Identifies strategic opportunities and threats
    - Provides competitive intelligence
    - Generates actionable market insights
    """
    
    def __init__(
        self,
        overmind_tracer: OvermindTracer = None,
        llm_client: Any = None,
        cursor_composer: CursorComposerService = None,
    ):
        """
        Initialize market analysis agent.
        
        Args:
            overmind_tracer: Overmind tracer instance
            llm_client: LLM client for analysis
            cursor_composer: Cursor Composer 2.5 service
        """
        super().__init__(
            name="MarketAnalysisAgent",
            overmind_tracer=overmind_tracer,
            llm_client=llm_client,
            cursor_composer=cursor_composer,
        )
    
    async def analyze_market_intelligence(
        self,
        intelligence_data: Dict,
        campaign_context: Dict,
        historical_analysis: List[Dict] = None
    ) -> List[MarketInsight]:
        """
        Analyze market intelligence and generate strategic insights.
        
        This is the main agent function - uses LLM to transform raw intelligence
        into actionable strategic insights. Traced with Overmind for optimization.
        
        Args:
            intelligence_data: Raw intelligence from Tavily, BERTopic, etc.
            campaign_context: Campaign context and goals
            historical_analysis: Previous analyses for trend identification
        
        Returns:
            List of strategic market insights
        """
        # Use Overmind tracing if available
        if self.overmind_tracer.initialized:
            return await self._analyze_with_tracing(intelligence_data, campaign_context, historical_analysis)
        else:
            return await self._analyze_without_tracing(intelligence_data, campaign_context, historical_analysis)
    
    async def _analyze_with_tracing(
        self,
        intelligence_data: Dict,
        campaign_context: Dict,
        historical_analysis: List[Dict] = None
    ) -> List[MarketInsight]:
        """Execute analysis with Overmind tracing."""
        with self.overmind_tracer.start_span("market_analysis_intelligence"):
            self.overmind_tracer.set_custom_tag("agent", self.name)
            self.overmind_tracer.set_custom_tag("intelligence_sources", str(len(intelligence_data)))
            return await self._analyze_without_tracing(intelligence_data, campaign_context, historical_analysis)
    
    async def _analyze_without_tracing(
        self,
        intelligence_data: Dict,
        campaign_context: Dict,
        historical_analysis: List[Dict] = None
    ) -> List[MarketInsight]:
        """Execute analysis without Overmind tracing (fallback)."""
        # Store context in memory
        self.memory.store("current_intelligence", intelligence_data)
        self.memory.store("campaign_context", campaign_context)
        self.memory.store("historical_analysis", historical_analysis or [])
        
        # Build prompt for LLM
        prompt = self._build_analysis_prompt(
            intelligence_data,
            campaign_context,
            historical_analysis
        )
        
        # Call LLM for strategic analysis (with Overmind tracing)
        response = await self.think(
            prompt=prompt,
            context={
                "intelligence_data": intelligence_data,
                "campaign_context": campaign_context
            }
        )
        
        # Parse LLM response into structured insights
        insights = self._parse_insights_response(response, intelligence_data)
        
        # Record analysis
        self.memory.record_decision(
            agent_name=self.name,
            decision=f"Generated {len(insights)} market insights",
            reasoning=f"Analysis based on intelligence from {len(intelligence_data)} sources",
            context={"intelligence_sources": list(intelligence_data.keys())}
        )
        
        return insights
    
    def _build_analysis_prompt(
        self,
        intelligence_data: Dict,
        campaign_context: Dict,
        historical_analysis: List[Dict]
    ) -> str:
        """
        Build prompt for market analysis.
        
        Args:
            intelligence_data: Intelligence data
            campaign_context: Campaign context
            historical_analysis: Historical analyses
        
        Returns:
            LLM prompt
        """
        goal = campaign_context.get("goal", "unknown")
        category = campaign_context.get("category", "unknown")
        target_audience = campaign_context.get("target_audience", "unknown")
        
        # Format intelligence data
        intel_summary = self._format_intelligence_summary(intelligence_data)
        
        # Format historical context
        historical_context = ""
        if historical_analysis:
            recent_insights = historical_analysis[-3:]  # Last 3 analyses
            historical_context = f"""
RECENT INSIGHTS (for trend identification):
{chr(10).join([f"- {insight.get('summary', 'No summary')}" for insight in recent_insights])}
"""
        
        prompt = f"""You are an expert market analyst for media buying. Analyze the following intelligence and provide strategic insights:

CAMPAIGN CONTEXT:
- Goal: {goal}
- Category: {category}
- Target Audience: {target_audience}

MARKET INTELLIGENCE:
{intel_summary}

{historical_context}

Generate 3-5 strategic insights covering:
1. Market opportunities (untapped demand, emerging trends)
2. Competitive threats (new entrants, aggressive competitors)
3. Audience behavior changes (shifting preferences, new patterns)
4. Strategic recommendations (specific actions to take)

For each insight, provide:
- Type (opportunity/threat/observation)
- Summary (2-3 sentences)
- Evidence (specific data points)
- Confidence level (0-1)
- Actionability (immediate/short-term/long-term)
- Urgency (high/medium/low)
- Specific recommendations"""
        
        return prompt
    
    def _format_intelligence_summary(self, intelligence_data: Dict) -> str:
        """Format intelligence data for prompt."""
        summary_parts = []
        
        for source, data in intelligence_data.items():
            if source == "market_intelligence":
                answer = data.get("answer", "No market intelligence available")
                summary_parts.append(f"MARKET INTELLIGENCE:\n{answer[:500]}")
            
            elif source == "social_sentiment":
                top_posts = data[:3] if isinstance(data, list) else []
                posts_summary = "\n".join([f"- {post.get('title', 'No title')}" for post in top_posts])
                summary_parts.append(f"SOCIAL SENTIMENT:\n{posts_summary}")
            
            elif source == "competitor_activity":
                for competitor in data:
                    comp_name = competitor.get("competitor", "Unknown")
                    topics = [t.get("topic", "") for t in competitor.get("results", [])]
                    summary_parts.append(f"COMPETITOR {comp_name}:\nTopics: {', '.join(topics[:3])}")
        
        return "\n\n".join(summary_parts) if summary_parts else "No intelligence data available"
    
    def _parse_insights_response(
        self,
        response: str,
        intelligence_data: Dict
    ) -> List[MarketInsight]:
        """
        Parse LLM response into structured insights.
        
        Args:
            response: LLM response text
            intelligence_data: Original intelligence data
        
        Returns:
            List of structured market insights
        """
        # In production, this would properly parse the LLM response
        # For now, generate sample insights based on data
        
        insights = []
        
        # Generate insight based on available intelligence
        if "market_intelligence" in intelligence_data:
            insights.append(MarketInsight(
                insight_type="opportunity",
                summary="Emerging market trend detected in audience conversations",
                evidence=["Increased mention frequency in social data", "High intent score in topic analysis"],
                confidence=0.85,
                actionability="immediate",
                urgency="medium",
                recommendations=["Create content targeting this trend", "Increase bid on related keywords"]
            ))
        
        if "competitor_activity" in intelligence_data:
            insights.append(MarketInsight(
                insight_type="threat",
                summary="Competitor increasing activity in key segments",
                evidence=["New competitor content detected", "Increased competitive density"],
                confidence=0.78,
                actionability="short-term",
                urgency="high",
                recommendations=["Differentiate messaging", "Focus on untapped sub-segments"]
            ))
        
        if len(insights) == 0:
            insights.append(MarketInsight(
                insight_type="observation",
                summary="Market conditions stable, no major changes detected",
                evidence=["Consistent intelligence patterns", "Normal activity levels"],
                confidence=0.70,
                actionability="long-term",
                urgency="low",
                recommendations=["Continue monitoring", "Maintain current strategy"]
            ))
        
        return insights
    
    async def analyze_competition(
        self,
        competitor_data: List[Dict],
        market_position: Dict
    ) -> CompetitiveAnalysis:
        """
        Analyze competitive landscape.
        
        Args:
            competitor_data: Data about competitors
            market_position: Current market position
        
        Returns:
            Competitive analysis with strategic assessment
        """
        prompt = f"""Analyze the competitive landscape:

COMPETITOR DATA:
{self._format_competitor_data(competitor_data)}

OUR MARKET POSITION:
{market_position}

Provide:
1. Key competitor movements (new strategies, content, targeting)
2. Market opportunities they're missing
3. Threat assessment (immediate/medium/long-term threats)
4. Our strategic position (leader/challenger/niche)"""
        
        analysis = await self.think(
            prompt=prompt,
            context={"competitor_data": competitor_data, "market_position": market_position}
        )
        
        return CompetitiveAnalysis(
            competitor_movements=[{"competitor": c.get("name", "Unknown"), "activity": "Recent activity detected"} for c in competitor_data],
            market_opportunities=[{"opportunity": "Underserved segment identified", "potential": "high"}],
            threat_assessment="Moderate competitive pressure",
            strategic_position="Challenger with growth potential"
        )
    
    def _format_competitor_data(self, competitor_data: List[Dict]) -> str:
        """Format competitor data for prompt."""
        if not competitor_data:
            return "No competitor data available"
        
        return "\n".join([
            f"{c.get('name', 'Unknown')}: {c.get('activity', 'No activity data')}"
            for c in competitor_data
        ])
    
    async def predict_market_trends(
        self,
        historical_intelligence: List[Dict],
        time_horizon: str = "30d"
    ) -> List[Dict]:
        """
        Predict future market trends based on historical intelligence.
        
        Args:
            historical_intelligence: Historical intelligence data
            time_horizon: Prediction time horizon
        
        Returns:
            Predicted market trends
        """
        prompt = f"""Based on historical market intelligence, predict future trends:

HISTORICAL INTELLIGENCE (Last 90 days):
{self._format_historical_intelligence(historical_intelligence)}

TIME HORIZON: {time_horizon}

Predict:
1. Emerging topics/themes
2. Audience behavior changes
3. Competitive landscape shifts
4. Technology/platform changes

For each prediction, provide confidence and potential impact."""
        
        predictions = await self.think(
            prompt=prompt,
            context={"historical_intelligence": historical_intelligence, "time_horizon": time_horizon}
        )
        
        return [
            {
                "trend": "Increased focus on sustainability messaging",
                "confidence": 0.75,
                "impact": "high",
                "timeframe": "30-60 days"
            }
        ]  # Placeholder
    
    def _format_historical_intelligence(self, historical_intelligence: List[Dict]) -> str:
        """Format historical intelligence for prompt."""
        if not historical_intelligence:
            return "No historical data available"
        
        # Summarize key trends from historical data
        return f"Analysis of {len(historical_intelligence)} data points showing market evolution over time"